DROP TABLE IF EXISTS `tikis_platform_settings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tikis_platform_settings` (
  `id` int NOT NULL,
  `commissionRate` decimal(6,5) NOT NULL DEFAULT '0.10000',
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `referralRewardAmount` int NOT NULL DEFAULT '1000',
  `referralEnabled` tinyint(1) NOT NULL DEFAULT '1',
  `minWithdrawal` int NOT NULL DEFAULT '500',
  `maxWithdrawal` int NOT NULL DEFAULT '500000',
  `pricingConfig` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `maintenanceEnabled` tinyint(1) NOT NULL DEFAULT '0',
  `maintenanceMessage` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `referralRequiredDeliveries` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
