  `tokenHash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tokenLast4` varchar(4) COLLATE utf8mb4_unicode_ci NOT NULL,
  `deviceName` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `platform` enum('ios','android','web','unknown') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unknown',
  `appVersion` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ipAddress` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `lastSeenAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `revokedAt` timestamp NULL DEFAULT NULL,
  KEY `tikis_profile_sessions_phone_index` (`phone`,`lastSeenAt`),
